-- Ulduar: the spell target conditions (source type 13, SourceGroup is the effect mask) the world lacked, from TrinityCore 3.3.5.
-- Without them the entry-based targets (nearby entry, area entry, cone entry) accept any unit in range.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` IN (61964, 62016, 62466, 62483, 62484, 62485, 62560, 62565, 62577, 62646, 62809, 62942, 62976, 63238, 63820, 64402, 64425, 64463, 64539, 64543, 64570, 64619, 64620, 64626, 64799, 65034, 65101, 65192, 65354);
